#include <bits/stdc++.h>
using namespace std;

int maxLength(const string& s) {
    string result = "";
    bool inParentheses = false;
    for (size_t i = 0; i < s.length(); i++) {
        char c = s[i];
        if (c == '(')
            inParentheses = true;
        else if (c == ')') {
            inParentheses = false;
            result += "_";
        }
        if (!inParentheses && c != ')')
            result += c;
    }
    int maxLen = 0;
    size_t start = 0;
    for (size_t i = 0; i <= result.length(); i++) {
        if (i == result.length() || result[i] == '_') {
            maxLen = max(maxLen, (int)(i - start));
            start = i + 1;
        }
    }
    return maxLen;
}

int count(const string& s) {
    int cnt = 0;
    size_t start = 0;
    for (size_t i = 0; i <= s.length(); i++) {
        if (i == s.length() || s[i] == '_') {
            if (i - start != 0)
                cnt++;
            start = i + 1;
        }
    }
    return cnt;
}

int words(const string& s) {
    int totalWords = 0;
    string temp = "";
    bool inside = false;
    for (size_t i = 0; i < s.length(); i++) {
        char c = s[i];
        if (c == '(')
            inside = true;
        else if (c == ')') {
            inside = false;
            totalWords += count(temp);
            temp.clear();
        } else if (inside && c != '(') {
            temp += c;
        }
    }
    return totalWords;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    cout << maxLength(s) << " " << words(s) << "\n";
    return 0;
}

